const $=s=>document.querySelector(s),size=n=>(n/1073741824).toFixed(2)+' GB';
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const result=await response.json();if(!response.ok)throw Error(result.error?.message||'操作失败。');return result;}
async function load(){try{const result=await api('/api/admin/users');$('#users').replaceChildren();for(const user of result.users){const row=document.createElement('tr');for(const text of [user.email,user.role==='admin'?'管理员':user.enabled?'用户':'已停用',size(user.used)+' / '+size(user.quota_bytes)]){const cell=document.createElement('td');cell.textContent=text;row.append(cell);}const actions=document.createElement('td');const quota=document.createElement('button');quota.textContent='设置容量';quota.onclick=async()=>{const value=prompt('用户容量（GB，按 1024³ 字节计算）',String(user.quota_bytes/1073741824));if(value===null)return;const bytes=Math.round(Number(value)*1073741824);if(!Number.isSafeInteger(bytes)||bytes<0){$('#feedback').textContent='请输入有效容量。';return;}try{await api('/api/admin/users/'+user.id,{method:'PATCH',body:JSON.stringify({quotaBytes:bytes})});await load();}catch(error){$('#feedback').textContent=error.message;}};actions.append(quota);if(user.role!=='admin'){const toggle=document.createElement('button');toggle.textContent=user.enabled?'停用':'启用';toggle.onclick=async()=>{try{await api('/api/admin/users/'+user.id,{method:'PATCH',body:JSON.stringify({enabled:!user.enabled})});await load();}catch(error){$('#feedback').textContent=error.message;}};actions.append(' ',toggle);}row.append(actions);$('#users').append(row);}}catch(error){$('#feedback').textContent=error.message;}}
$('#invite-form').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/admin/invites',{method:'POST',body:JSON.stringify({email:$('#invite-email').value})});const link=document.createElement('a');link.href=result.url;link.textContent=result.url;$('#invite-link').replaceChildren('设置链接（24 小时有效，请私下交给对应用户）：',link);await load();}catch(error){$('#feedback').textContent=error.message;}};
load();
